<script setup lang="ts">
import {computed,watch} from 'vue'
import type {AuthorValue} from './types'
const props=defineProps<{value:AuthorValue}>(),places=computed(()=>props.value.definition.entities.filter(e=>e.type==='place')),characters=computed(()=>props.value.definition.entities.filter(e=>e.type==='character')),items=computed(()=>props.value.definition.entities.filter(e=>e.type==='item'))
watch(()=>characters.value.map(e=>e.id),ids=>{for(const id of ids)props.value.definition.initial[id]??={alive:true,location:props.value.definition.location,inventory:{},fields:{},relations:{},known:[]}},{immediate:true})
function setRoute(id:string,event:Event){const selected=[...(event.target as HTMLSelectElement).selectedOptions].map(o=>o.value),routes=props.value.rules.routes??={};routes[id]=selected;for(const place of places.value.filter(p=>p.id!==id)){const neighbors=routes[place.id]??=[];routes[place.id]=selected.includes(place.id)?[...new Set([...neighbors,id])]:neighbors.filter(other=>other!==id)}}
function inventory(character:string,item:string,event:Event){const count=Number((event.target as HTMLInputElement).value);props.value.definition.initial[character].inventory[item]=Math.max(0,Math.trunc(count))}
</script>
<template><section><h2>地点与初始状态</h2><label>世界起始地点<select aria-label="世界起始地点" v-model="value.definition.location"><option v-for="place in places" :key="place.id" :value="place.id">{{place.name}}</option></select></label><article v-for="place in places" :key="place.id" class="author-item"><h3>{{place.name}}的路线</h3><label>可直接到达（多选）<select aria-label="可直接到达（多选）" multiple :value="value.rules.routes?.[place.id]||[]" @change="setRoute(place.id,$event)"><option v-for="other in places.filter(p=>p.id!==place.id)" :key="other.id" :value="other.id">{{other.name}}</option></select><small>路线会同时连通两个地点。删除地点前，先清除相关路线与开局引用。</small></label></article><article v-for="character in characters" :key="character.id" class="author-item"><h3>{{character.name}}的初始状态</h3><label>人物初始地点<select aria-label="人物初始地点" v-model="value.definition.initial[character.id].location"><option v-for="place in places" :key="place.id" :value="place.id">{{place.name}}</option></select></label><label class="author-check"><input v-model="value.definition.initial[character.id].alive" type="checkbox">开场时存活</label><label v-for="item in items" :key="item.id">{{item.name}}初始数量<input type="number" min="0" step="1" :value="value.definition.initial[character.id].inventory[item.id]||0" @input="inventory(character.id,item.id,$event)"></label></article></section></template>
